// DSHA_STATIC_CACHE_V3: weak HTTP validators match lists and wildcard values.
function dshaRevalidated(value, etag) {
	if (value === null) return false;
	const normalized = etag.replace(/^W\//, "");
	return value.split(",").some(part => {
		const tag = part.trim();
		return tag === "*" || tag.replace(/^W\//, "") === normalized;
	});
}
